import{_ as i,a0 as o,w as r,s as u,I as n,x as e,a1 as t,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"使用 Powershell 來自動化 Linux、macOS 以及 Windows 流程 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Powershell 來自動化 Linux、macOS 以及 Windows 流程 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Powershell 來自動化 Linux、macOS 以及 Windows 流程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Powershell 來自動化 Linux、macOS 以及 Windows 流程 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20200207 Using Powershell to automate Linux, macOS, and Windows processes","title":"使用 Powershell 來自動化 Linux、macOS 以及 Windows 流程","tag":"202111","desc":""},"relativePath":"202111/20200207 Using Powershell to automate Linux, macOS, and Windows processes.md","filePath":"[post].md"}'),c={name:"202111/20200207 Using Powershell to automate Linux, macOS, and Windows processes.md"};function m(d,s,h,g,T,w){const a=o("Link");return r(),u("div",null,[s[26]||(s[26]=n("h1",{id:"使用-powershell-來自動化-linux、macos-以及-windows-流程",tabindex:"-1"},[e("使用 Powershell 來自動化 Linux、macOS 以及 Windows 流程 "),n("a",{class:"header-anchor",href:"#使用-powershell-來自動化-linux、macos-以及-windows-流程","aria-label":"Permalink to “使用 Powershell 來自動化 Linux、macOS 以及 Windows 流程”"},"​")],-1)),s[27]||(s[27]=n("blockquote",null,[n("p",null,"自動化是 DevOps 的關鍵，但是，是否任何事都可以自動化？")],-1)),s[28]||(s[28]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/23/123000eexe7iez7wsew72e.jpg",alt:""})],-1)),s[29]||(s[29]=n("p",null,"自動化控制了那些手工的、費力的和容易出錯的過程，用運行自動化腳本的計算機代替了執行手工任務的工程師。每個人都認同手工流程是健康的 DevOps 模式的敵人。一些人認為自動化不是一件好事，因為它取代了辛勤工作的工程師，而另一些人則意識到它提高了一致性、可靠性和效率，節省了時間，（最重要的是）使工程師能夠聰明地工作。",-1)),n("blockquote",null,[n("p",null,[s[1]||(s[1]=e("“DevOps 並不只是自動化或者基礎架構即代碼。” — ",-1)),t(a,{href:"http://www.donovanbrown.com/post/what-is-devops"},{default:p(()=>[...s[0]||(s[0]=[e("Donovan Brown",-1)])]),_:1})])]),s[30]||(s[30]=l('<p>自從上個世紀 80 年代早期開始使用自動化流程和工具鏈以來，每當我聽到或讀到“自動化一切”的建議時，我總是會激動不已。雖然在技術上可以實現一切自動化，但自動化是複雜的，並且需要付出開發、調試和維護方面的代價。如果你曾經重新啓用一個許久不用的 Azure 資源管理器（ARM）模板或很久以前編寫的寶貴維護腳本，並期望它在幾個月或幾年之後仍然能夠完美地執行，那麼你就會明白，自動化就像任何其他代碼一樣，是脆弱的，需要持續的維護和培養。</p><p>所以，你應該對什麼進行自動化並在何時進行自動化？</p><ul><li>當你手動執行自動化流程超過一兩次</li><li>當你需要經常地持續地執行自動化流程</li><li>自動化任何可被自動化的</li></ul><p>更重要的是，什麼是你不應該自動化的？</p><ul><li>不要自動化一次性的流程，因為不值得投入，除非你會重新使用它作為參考文檔，並定期驗證它的可用性</li><li>不要自動化高度不穩定的流程，因為太複雜且昂貴</li><li>不要自動化有問題的流程，在自動化前先修復它們</li></ul><p>舉例來説，我的團隊使用我們通用的協作和工程系統來不斷的監控數百個用户活動。如果一個用户在三個月或者更長時間處於非活動狀態，並且這個用户被分配了一個昂貴的許可證，我們就會重分配這個用户一個功能少一些但是免費的許可證。</p><p>如圖 1 所示，這是一個沒有技術挑戰性的流程。這是一個令人費解且容易出錯的過程，尤其是在執行上下文時與其他開發和運維任務切換時。</p><p><img src="https://opensource.com/sites/default/files/uploads/devops_quest_to_automate_1.png" alt="Manual process to switch user license" title="Manual process to switch user license"></p><p><em>圖 1 手工流程切換用户許可證</em></p><p>順帶的，這裏有一個用簡單三步創建的價值流圖的例子:</p><ol><li>可視化所有活動: 列出用户、過濾用户、重置許可證。</li><li>確定利益相關者，即運營和授權團隊。</li><li>措施： * 總交貨時間（TLT）= 13 小時 * 總週期時間（TCT） = 1.5 小時 * 總效率百分比 = TLT/TCT*100 = 11.5%</li></ol><p>如果你在人羣流量大和容易看到的區域掛一個這些可視化的副本，比如在你的團隊的討論區、餐廳，或在去洗手間的路上，你將引發大量的討論和主動反饋。例如，從視覺上看，很明顯，手工任務是一種浪費，主要是由於漫長的流程等待時間造成的。</p><p>讓我們研究一個簡單的 PowerShell 腳本，它可以自動化該流程，如圖 2 所示，將總交付時間從 13 小時減少到 4 小時加 60 秒，並將總體效率從 11.5 提高到 12.75%。</p><p><img src="https://opensource.com/sites/default/files/uploads/the_devops_quest_to_automate_everything_automatable_using_powershell_picture_2.png" alt="Semi-automated PowerShell-based process to switch user license" title="Semi-automated PowerShell-based process to switch user license"></p><p><em>圖 2 半自動化的 PowerShell 腳本切換用户許可</em></p>',15)),n("p",null,[t(a,{href:"https://opensource.com/article/19/8/variables-powershell"},{default:p(()=>[...s[2]||(s[2]=[e("PowerShell",-1)])]),_:1}),s[4]||(s[4]=e(" 是一種開源的基於任務的腳本語言。它可以在 ",-1)),t(a,{href:"https://github.com/powershell/powershell"},{default:p(()=>[...s[3]||(s[3]=[e("GitHub",-1)])]),_:1}),s[5]||(s[5]=e(" 上找到。它構建在 .NET 上，允許你自動化 Linux、macOS 和 Windows 流程。具有開發背景的用户，特別是 C# 用户，將享受到 PowerShell 的全部好處。",-1))]),n("p",null,[s[8]||(s[8]=e("下面的 PowerShell 腳本示例通過它的服務 ",-1)),t(a,{href:"https://docs.microsoft.com/en-us/rest/api/azure/devops/?view=azure-devops-rest-5.1"},{default:p(()=>[...s[6]||(s[6]=[e("REST API",-1)])]),_:1}),s[9]||(s[9]=e(" 與 ",-1)),t(a,{href:"https://docs.microsoft.com/en-us/azure/devops/user-guide/what-is-azure-devops?view=azure-devops"},{default:p(()=>[...s[7]||(s[7]=[e("Azure DevOps",-1)])]),_:1}),s[10]||(s[10]=e(" 進行通信。腳本結合了在圖 1 中的手動列表用户和過濾用户任務，識別了 Demo 組織中的所有兩個月沒有活動的、使用基本許可證或更昂貴的基本+測試許可證的用户，並將用户的詳細信息輸出到控制台。很簡單！",-1))]),s[31]||(s[31]=l(`<p>首先，設置認證標頭和其他變量，這些變量將在稍後的初始化腳本中使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>param(</span></span>
<span class="line"><span>  [string]   $orgName       = &quot;DEMO&quot;,</span></span>
<span class="line"><span>  [int]      $months        = &quot;-2&quot;,</span></span>
<span class="line"><span>  [string]   $patToken      = &quot;&lt;PAT&gt;&quot;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Basic authentication header using the personal access token (PAT)</span></span>
<span class="line"><span>$basicAuth = (&quot;{0}:{1}&quot; -f &quot;&quot;,$patToken)</span></span>
<span class="line"><span>$basicAuth = [System.Text.Encoding]::UTF8.GetBytes($basicAuth)</span></span>
<span class="line"><span>$basicAuth = [System.Convert]::ToBase64String($basicAuth)</span></span>
<span class="line"><span>$headers   = @{Authorization=(&quot;Basic {0}&quot; -f $basicAuth)}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># REST API Request to get all entitlements</span></span>
<span class="line"><span>$request_GetEntitlements    = &quot;https://vsaex.dev.azure.com/&quot; + $orgName + &quot;/_apis/userentitlements?top=10000&amp;api-version=5.1-preview.2&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Initialize data variables</span></span>
<span class="line"><span>$members              = New-Object System.Collections.ArrayList</span></span>
<span class="line"><span>[int] $count          = 0;</span></span>
<span class="line"><span>[string] $basic       = &quot;Basic&quot;;</span></span>
<span class="line"><span>[string] $basicTest   = &quot;Basic + Test Plans&quot;;</span></span></code></pre></div><p>接下來，使用此腳本查詢所有授權，以識別不活動用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Send the REST API request and initialize the members array list.</span></span>
<span class="line"><span>$response = Invoke-RestMethod -Uri $request_GetEntitlements -headers $headers -Method Get</span></span>
<span class="line"><span>$response.items | ForEach-Object { $members.add($_.id) | out-null }</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Iterate through all user entitlements</span></span>
<span class="line"><span>$response.items | ForEach-Object {</span></span>
<span class="line"><span>  $name    = [string]$_.user.displayName;</span></span>
<span class="line"><span>  $date    = [DateTime]$_.lastAccessedDate;</span></span>
<span class="line"><span>  $expired = Get-Date;</span></span>
<span class="line"><span>  $expired = $expired.AddMonths($months);</span></span>
<span class="line"><span>  $license = [string]$_.accessLevel.AccountLicenseType;</span></span>
<span class="line"><span>  $licenseName = [string]$_.accessLevel.LicenseDisplayName;</span></span>
<span class="line"><span>  $count++;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  if ( $expired -gt $date ) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # Ignore users who have NEVER or NOT YET ACTIVATED their license</span></span>
<span class="line"><span>    if ( $date.Year -eq 1 ) {</span></span>
<span class="line"><span>      Write-Host &quot; **INACTIVE** &quot; &quot; Name: &quot; $name &quot; Last Access: &quot; $date &quot;License: &quot; $licenseName</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    # Look for BASIC license</span></span>
<span class="line"><span>    elseif ( $licenseName -eq $basic ) {</span></span>
<span class="line"><span>         Write-Host &quot; **INACTIVE** &quot; &quot; Name: &quot; $name &quot; Last Access: &quot; $date &quot;License: &quot; $licenseName</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    # Look for BASIC + TEST license</span></span>
<span class="line"><span>    elseif ( $licenseName -eq $basicTest ) {</span></span>
<span class="line"><span>        Write-Host &quot; **INACTIVE** &quot; &quot; Name: &quot; $name &quot; Last Access: &quot; $date &quot;License: &quot; $licenseName</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>當你運行腳本時，你將得到以下輸出，你可以將其轉發給授權團隊，以重置用户許可證：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>**INACTIVE** Name: Demo1 Last Access: 2019/09/06 11:01:26 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo2 Last Access: 2019/06/04 08:53:15 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo3 Last Access: 2019/09/26 12:54:57 PM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo4 Last Access: 2019/06/07 12:03:18 PM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo5 Last Access: 2019/07/18 10:35:11 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo6 Last Access: 2019/10/03 09:21:20 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo7 Last Access: 2019/10/02 11:45:55 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo8 Last Access: 2019/09/20 01:36:29 PM License: Basic + Test Plans</span></span>
<span class="line"><span>**INACTIVE** Name: Demo9 Last Access: 2019/08/28 10:58:22 AM License: Basic</span></span></code></pre></div><p>如果你將最後一步自動化，自動將用户許可設置為一個自由的利益相關方許可，如圖3所示，你可以進一步將總體交付時間減少到65秒，並將總體效率提高到77%。</p><p><img src="https://opensource.com/sites/default/files/uploads/devops_quest_to_automate_3.png" alt="Fully automated PowerShell-based process to switch user license" title="Fully automated PowerShell-based process to switch user license"></p><p><em>圖 3 完全自動化的基於 Powershell 的流程來切換用户許可證。</em></p><p>這個 PowerShell 腳本的核心價值不僅在於能夠實現 <em>自動化</em>，還在於能夠 <em>定期</em>、<em>持續</em> 和 <em>快速地</em> 執行這個流程。進一步的改進是使用 Azure 管道等調度器每週或每天觸發腳本，但我將把程序化的許可證重置和腳本調度保留在未來的文章中。</p><p>這裏有一個圖表，可以直觀地看到進展情況：</p><p><img src="https://opensource.com/sites/default/files/uploads/devops_quest_to_automate_4.png" alt="Graph to visualize progress" title="Graph to visualize progress"></p><p><em>圖 4，措施，措施，措施</em></p><p>我希望你能喜歡這個簡短的關於自動化、PowerShell、REST API 和價值流圖的介紹。請在評論中分享你的想法和反饋。</p><hr>`,15)),n("p",null,[s[12]||(s[12]=e("via: ",-1)),t(a,{href:"https://opensource.com/article/20/2/devops-automation"},{default:p(()=>[...s[11]||(s[11]=[e("https://opensource.com/article/20/2/devops-automation",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=e("作者：",-1)),t(a,{href:"https://opensource.com/users/wpschaub"},{default:p(()=>[...s[13]||(s[13]=[e("Willy-Peter Schaub",-1)])]),_:1}),s[18]||(s[18]=e(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 譯者：",-1)),t(a,{href:"https://github.com/FigaroCao"},{default:p(()=>[...s[15]||(s[15]=[e("FigaroCao",-1)])]),_:1}),s[20]||(s[20]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:p(()=>[...s[22]||(s[22]=[e("Linux中國",-1)])]),_:1}),s[25]||(s[25]=e(" 榮譽推出",-1))])])}const q=i(c,[["render",m]]);export{b as __pageData,q as default};
